    { "id": 45, "name": "Capital Offense", "description": "Smash your way out of a vehicle showroom in classic style.", "grade": "bronze", "hidden": true, "kind": "crime", "stage": 6, "chapter": "Ch 3+", "difficulty": 2, "time": "Ch 3+", "missable": false, "unconfirmed": false,
      "guide": "Smash your way out of a vehicle showroom in classic style. Steal the blue Banshee from the showroom in south Vice City and drive it straight through the window — a GTA III easter egg. You need the Key Cloner first, from Chapter 3's Clonin' Keys, Makin' Gs. Only the blue Banshee counts; the pop is slightly delayed, after you drive away down the street.",
      "steps": ["Get the Key Cloner (Chapter 3's Clonin' Keys, Makin' Gs)", "Go to the showroom in south Vice City", "Steal the blue Banshee and drive it through the window"],
      "sources": [1, 2, 5] },
    { "id": 46, "name": "Let's Go Bowling", "description": "Follow-through at the Kolt & Associates' bowling alley.", "grade": "bronze", "hidden": true, "kind": "crime", "stage": 6, "chapter": "Ch 2", "difficulty": 2, "time": "Ch 2", "missable": false, "unconfirmed": false,
      "guide": "Follow-through at the Kolt & Associates' bowling alley. Rob all 3 key valuables at Kingpin Bowling in Port Gellhorn (an illegal operation, marked during Chapter 2's Hit Kingpin Bowling): the luxury watch in the south-east office, the Gutterball Moreland 850 shotgun on a table in the north-east corner, and the office safe in the north-east hallway — blow it with a Sticky Bomb (buy them at Ammu-Nation first). The trophy pops after you escape the police, not when you grab the third item. Not missable: if you miss an item, the robbery icon respawns later and you can grab what is left.",
      "steps": ["Buy Sticky Bombs at an Ammu-Nation", "Go to Kingpin Bowling in Port Gellhorn (Chapter 2's Hit Kingpin Bowling)", "Take the watch, the shotgun and the safe contents", "Escape the police — the trophy pops then, not at the third item"],
      "sources": [1, 2, 5] },
    { "id": 47, "name": "Personal Best", "description": "A partnership with mass appeal.", "grade": "bronze", "hidden": true, "kind": "misc", "stage": 7, "chapter": "Ch 2+", "difficulty": 3, "time": "4–6 h", "missable": false, "unconfirmed": false,
      "guide": "A partnership with mass appeal — maximum Strength with both Jason and Lucia at the same time. After Coffee Break (Chapter 2) you can switch characters; buy a gym membership and always train together (call your partner) — while one works out, the other trains too, doubling progress. Check Strength under Touchpad > Jason & Lucia. Gyms are filterable on the map under Activities; you can also work out at home after the story.",
      "steps": ["After Coffee Break, buy a gym membership", "Always train with your partner along (double progress)", "Bring both characters to maximum Strength"],
      "sources": [1, 2, 5] },
    { "id": 48, "name": "Actions Speak Louder", "description": "Choices made (for better or worse).", "grade": "bronze", "hidden": true, "kind": "misc", "stage": 7, "chapter": "Anytime", "difficulty": 2, "time": "Across the run", "missable": false, "unconfirmed": false, "target": { "label": "profile actions", "total": 500 },
      "guide": "Choices made (for better or worse) — perform 500 actions that affect your Criminal Profile. Turn on profile notifications (Settings > UI > HUD Notifications > Criminal Profile = On) and watch for the demon face on the right of the screen. Robberies, fights and escapes all feed it, and it fills passively while you chase other trophies. Profiles run Professional, Hardened, Violent, Psycho, then Irredeemable — the last one is permanent, so avoid it: cops shoot on sight more often.",
      "steps": ["Turn on Criminal Profile notifications in Settings > UI", "Play normally — robberies and fights feed the counter", "It fills passively; check the count on the trophy itself"],
      "sources": [1, 2, 5] },
