    { "id": 50, "name": "The Truth Is Out There", "description": "What the hell just happened?", "grade": "bronze", "hidden": true, "kind": "misc", "stage": 7, "chapter": "Anytime", "difficulty": 2, "time": "Anytime (night)", "missable": false, "unconfirmed": false,
      "guide": "What the hell just happened? — the UFO easter egg. Go solo, at night after 2AM, to the road north-west of Starlet Motel in Kelly County. Sometimes a blinking car is parked at the roadside; if it is not there, drive away and come back. Follow the path into the woods from the car and you will see the UFO (a bright blue light). Approach it — it drops a woman it abducted. Talk to her, offer to help, and go back to her car at the roadside. The spawn is slightly random, not guaranteed.",
      "steps": ["Go solo, at night after 2AM, to the road north-west of Starlet Motel (Kelly County)", "Look for the blinking car at the roadside — if absent, drive away and return", "Follow the path into the woods to the UFO", "Approach it, talk to the woman it drops, then return to her car"],
      "sources": [1, 2, 5] },
    { "id": 51, "name": "Ten Pin", "description": "Bowl 'em over with a melee drive-by.", "grade": "bronze", "hidden": true, "kind": "misc", "stage": 7, "chapter": "Anytime", "difficulty": 1, "time": "Unknown", "missable": false, "unconfirmed": true,
      "guide": "Bowl 'em over with a melee drive-by. UNCONFIRMED: PowerPyx lists this trophy as currently unknown, believed to be from kicking enemies while driving a motorcycle. No verified steps exist yet — the working theory is a melee kick from a moving bike. This guide will update once players confirm it.",
      "steps": ["No verified steps yet — listed honestly as unconfirmed", "Working theory: kick enemies while driving a motorcycle", "Check this guide again once players pin the trigger down"],
      "sources": [1, 2, 5],
      "unconfirmed_note": "PowerPyx lists this trophy as currently unknown, believed to be from kicking enemies while driving a motorcycle." },
    { "id": 52, "name": "Dime on the Dollar", "description": "Earn $250,000 laundering Marked Bills through your contacts.", "grade": "bronze", "hidden": false, "kind": "crime", "stage": 6, "chapter": "Ch 3+", "difficulty": 2, "time": "Ch 3+", "missable": false, "unconfirmed": false, "target": { "label": "marked bills laundered", "total": 250000, "unit": "$" },
      "guide": "Earn $250,000 laundering Marked Bills through your contacts. First finish Chapter 3's Credit Check (Meet Raul's Crew) — it unlocks the Dye Pack Jammer. Then rob banks and Payday Loans and bring the marked bills to a fence (Yasmani in Vice City pays the most). The $250,000 is cumulative across robberies. Bank vaults alone can pay up to $205,000 in a single job.",
      "steps": ["Finish Chapter 3's Credit Check to unlock the Dye Pack Jammer", "Rob banks and Payday Loans for marked bills", "Bring the bills to a fence — Yasmani pays the most", "Cumulative $250,000 across all robberies"],
      "sources": [1, 2, 5] },
    { "id": 53, "name": "Treat Yo Self", "description": "Spend $100,000 across all shops.", "grade": "bronze", "hidden": false, "kind": "misc", "stage": 7, "chapter": "Anytime", "difficulty": 1, "time": "Across the run", "missable": false, "unconfirmed": false, "target": { "label": "spent in shops", "total": 100000, "unit": "$" },
      "guide": "Spend $100,000 across all shops — cumulative across every shop type. Fastest on the expensive stuff: guns, car mods and tattoos. There are 24 Ammu-Nations, 67 clothing stores, 14 mod shops, 19 Pay 'n' Sprays, 11 tattoo studios and more — spending on cars, clothes and weapons all counts.",
      "steps": ["Spend across any shops — the $100,000 is cumulative", "Fastest: guns, car mods and tattoos", "It fills naturally while gearing up for other trophies"],
      "sources": [1, 2, 5] },
    { "id": 54, "name": "Little Boxes", "description": "Purchase all garage properties.", "grade": "bronze", "hidden": false, "kind": "collectibles", "stage": 5, "chapter": "Ch 2+", "difficulty": 1, "time": "Ch 2+", "missable": false, "unconfirmed": false, "target": { "label": "garages", "total": 8 },
      "guide": "Purchase all garage properties — 8 purchasable garages (plus 4 story garages that do not count), about $160,000 in total. They unlock after Chapter 2's Daily Driver (Steal the Crawler for Moses), when the Vice City Real Estate app lands on your phone. Buy them through the app. Robberies in Chapters 3–4 are the quick way to fund them — and garages also add the parking spots On the Spot needs.",
      "steps": ["Finish Chapter 2's Daily Driver", "Open the Vice City Real Estate app on your phone", "Buy all 8 garages (~$160,000 total)"],
      "sources": [1, 2, 5] },
    { "id": 55, "name": "On the Spot", "description": "Register 10 vehicles to the Scooter Bros app.", "grade": "bronze", "hidden": false, "kind": "misc", "stage": 7, "chapter": "Ch 2+", "difficulty": 1, "time": "Ch 2+", "missable": false, "unconfirmed": false, "target": { "label": "vehicles registered", "total": 10 },
      "guide": "Register 10 vehicles to the Scooter Bros app. The app arrives after Chapter 2's Moses (Take A Vehicle to Moses). Buy garages first — each adds parking spots. Drive a stolen car to Moses in Port Gellhorn, choose Respray then Register. At first he only takes cars without trackers; from Chapter 3, cars with standard trackers can be registered at any Pay 'n' Spray. Registering costs money — use cheap low-end cars and bikes.",
      "steps": ["Buy garages first (Little Boxes) for parking spots", "Finish Chapter 2's Moses to get the Scooter Bros app", "Drive stolen cars to Moses in Port Gellhorn", "Choose Respray, then Register — 10 vehicles in total"],
      "sources": [1, 2, 5] }
  ]
